// Construye el payload de la plantilla confirmacion_cita.
const d = $json.body || $json;
const nombre = String(d.nombre || 'cliente').trim().split(' ')[0];
const servicio = String(d.servicio || 'tu instalacion');
const fecha = String(d.fecha || 'la proxima semana');
const hora = String(d.hora || '10:00');
const telefono = String(d.telefono || '').replace(/\D/g, '');
return [{
  json: {
    telefono,
    nombre,
    payload: {
      messaging_product: 'whatsapp',
      to: telefono,
      type: 'template',
      template: {
        name: 'confirmacion_cita',
        language: { code: 'es' },
        components: [{
          type: 'body',
          parameters: [
            { type: 'text', text: nombre },
            { type: 'text', text: servicio },
            { type: 'text', text: fecha },
            { type: 'text', text: hora }
          ]
        }]
      }
    }
  }
}];
